let selectedDirectoryHandle;
let menuCatalogue=[];
let weeklySelection=new Set();
const pendingPhotos=new Map();
const folderButton=document.querySelector('#choose-folder');
const folderStatus=document.querySelector('#folder-status');
const editor=document.querySelector('#editor');
const libraryMount=document.querySelector('#library-list');
const itemsMount=document.querySelector('#items');
const itemTemplate=document.querySelector('#item-template');
const saveStatus=document.querySelector('#save-status');
const emptyState=document.querySelector('#empty-state');
const activeCount=document.querySelector('#active-count');
const starterCatalogue=[{id:'example-cake',title:'Example cake',category:'Cakes',description:"A short description of this week's delicious offering can go here.",price:'£4.00',image:'',glutenFree:false,vegan:false},{id:'example-treat',title:'Example treat',category:'Treats',description:"A short description of this week's delicious offering can go here.",price:'£4.00',image:'',glutenFree:false,vegan:false}];

function setStatus(element,message,isError=false){element.textContent=message;element.style.color=isError?'#9a254d':'';}
function makeId(){return `item-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;}
function normaliseItem(item){return{id:item.id||makeId(),title:item.title||'',category:item.category||'Other',description:item.description||'',price:item.price||'',image:item.image||'',glutenFree:Boolean(item.glutenFree),vegan:Boolean(item.vegan)};}
function openStorage(){return new Promise((resolve,reject)=>{const request=indexedDB.open('cookies-cakes-menu-manager',1);request.onupgradeneeded=()=>request.result.createObjectStore('settings');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
async function saveFolder(handle){const database=await openStorage();await new Promise((resolve,reject)=>{const transaction=database.transaction('settings','readwrite');transaction.objectStore('settings').put(handle,'website-folder');transaction.oncomplete=resolve;transaction.onerror=()=>reject(transaction.error);});database.close();}
async function getSavedFolder(){const database=await openStorage();const handle=await new Promise((resolve,reject)=>{const transaction=database.transaction('settings','readonly');const request=transaction.objectStore('settings').get('website-folder');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});database.close();return handle;}
function assignmentFrom(source,name){const match=source.match(new RegExp(`window\\.${name}\\s*=\\s*([\\s\\S]*?);\\s*(?=window\\.|$)`));return match?Function(`"use strict";return (${match[1]});`)():undefined;}
function readMenuData(source){const catalogue=assignmentFrom(source,'menuCatalogue');const selection=assignmentFrom(source,'weeklyMenuSelection');if(Array.isArray(catalogue))return{catalogue:catalogue.map(normaliseItem),selection:Array.isArray(selection)?selection:[]};const legacy=assignmentFrom(source,'weeklyMenuItems');if(Array.isArray(legacy)){const legacyCatalogue=legacy.map(normaliseItem);return{catalogue:legacyCatalogue,selection:legacyCatalogue.map(item=>item.id)};}return{catalogue:starterCatalogue,selection:starterCatalogue.map(item=>item.id)};}
function updateItemFromCard(card){const item=menuCatalogue.find(entry=>entry.id===card.dataset.id);if(!item)return;item.title=card.querySelector('[name="title"]').value;item.category=card.querySelector('[name="category"]').value||'Other';item.description=card.querySelector('[name="description"]').value;item.price=card.querySelector('[name="price"]').value;item.glutenFree=card.querySelector('[name="glutenFree"]').checked;item.vegan=card.querySelector('[name="vegan"]').checked;}
function syncActiveEdits(){itemsMount.querySelectorAll('.item-card').forEach(updateItemFromCard);}
function renderLibrary(){const groups={};menuCatalogue.forEach(item=>{const category=item.category.trim()||'Other';(groups[category]??=[]).push(item);});libraryMount.innerHTML='';Object.keys(groups).sort((a,b)=>a.localeCompare(b)).forEach(category=>{const group=document.createElement('section');group.className='category-group';const heading=document.createElement('h4');heading.textContent=category;group.append(heading);groups[category].sort((a,b)=>a.title.localeCompare(b.title)).forEach(item=>{const label=document.createElement('label');label.className='library-item';const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.checked=weeklySelection.has(item.id);checkbox.addEventListener('change',()=>{syncActiveEdits();if(checkbox.checked)weeklySelection.add(item.id);else weeklySelection.delete(item.id);renderLibrary();renderActiveItems();});const title=document.createElement('span');title.textContent=item.title||'Untitled item';label.append(checkbox,title);group.append(label);});libraryMount.append(group);});}
function createActiveCard(item){const fragment=itemTemplate.content.cloneNode(true);const card=fragment.querySelector('.item-card');card.dataset.id=item.id;card.querySelector('[name="title"]').value=item.title;card.querySelector('[name="category"]').value=item.category;card.querySelector('[name="description"]').value=item.description;card.querySelector('[name="price"]').value=item.price;card.querySelector('[name="glutenFree"]').checked=item.glutenFree;card.querySelector('[name="vegan"]').checked=item.vegan;const photoName=card.querySelector('.photo-name');photoName.textContent=pendingPhotos.has(item.id)?`New photo: ${pendingPhotos.get(item.id).name}`:(item.image?`Current photo: ${item.image}`:'No photo selected');card.querySelectorAll('input:not([type="file"]),textarea').forEach(input=>input.addEventListener('input',()=>updateItemFromCard(card)));card.querySelectorAll('input[type="checkbox"]').forEach(input=>input.addEventListener('change',()=>updateItemFromCard(card)));card.querySelectorAll('[name="title"],[name="category"]').forEach(input=>input.addEventListener('change',()=>{updateItemFromCard(card);renderLibrary();}));card.querySelector('[name="image"]').addEventListener('change',event=>{const file=event.target.files[0];if(file){pendingPhotos.set(item.id,file);photoName.textContent=`New photo: ${file.name}`;}});card.querySelector('.remove-item').addEventListener('click',()=>{if(!window.confirm(`Remove “${item.title||'this item'}” permanently from your menu library?`))return;menuCatalogue=menuCatalogue.filter(entry=>entry.id!==item.id);weeklySelection.delete(item.id);pendingPhotos.delete(item.id);renderLibrary();renderActiveItems();});itemsMount.append(card);}
function renderActiveItems(){itemsMount.innerHTML='';const activeItems=menuCatalogue.filter(item=>weeklySelection.has(item.id));activeItems.forEach(createActiveCard);emptyState.hidden=activeItems.length>0;activeCount.textContent=`${activeItems.length} active this week`;}
function addNewItem(){syncActiveEdits();const item=normaliseItem({id:makeId(),title:'New menu item',category:'Other',description:'',price:'',image:'',glutenFree:false,vegan:false});menuCatalogue.push(item);weeklySelection.add(item.id);renderLibrary();renderActiveItems();}
async function useFolder(handle){await handle.getFileHandle('menu.html');selectedDirectoryHandle=handle;let data={catalogue:starterCatalogue,selection:starterCatalogue.map(item=>item.id)};try{const dataFile=await handle.getFileHandle('menu-data.js');data=readMenuData(await (await dataFile.getFile()).text());}catch(error){console.warn(error);}menuCatalogue=data.catalogue;weeklySelection=new Set(data.selection);pendingPhotos.clear();renderLibrary();renderActiveItems();editor.hidden=false;setStatus(folderStatus,`Ready to edit: ${handle.name}`);}

folderButton.addEventListener('click',async()=>{if(!window.showDirectoryPicker){setStatus(folderStatus,'Please open this page in Chrome or Microsoft Edge to use the folder picker.',true);return;}try{const handle=await window.showDirectoryPicker({mode:'readwrite'});await useFolder(handle);await saveFolder(handle);}catch(error){if(error.name!=='AbortError')setStatus(folderStatus,'That folder could not be used. Please choose the cookiescakes_site folder.',true);}});
document.querySelector('#add-item').addEventListener('click',addNewItem);
document.querySelector('#menu-form').addEventListener('submit',async event=>{event.preventDefault();if(!selectedDirectoryHandle){setStatus(saveStatus,'Choose the website folder first.',true);return;}syncActiveEdits();if(!menuCatalogue.length){setStatus(saveStatus,'Add at least one item to your menu library before saving.',true);return;}try{setStatus(saveStatus,'Saving your menu library…');const imagesDirectory=await selectedDirectoryHandle.getDirectoryHandle('images',{create:true});for(let index=0;index<menuCatalogue.length;index+=1){const item=menuCatalogue[index];const photo=pendingPhotos.get(item.id);if(photo){const extension=(photo.name.match(/\.[a-zA-Z0-9]+$/)||['.jpg'])[0].toLowerCase();const safeTitle=(item.title||`item-${index+1}`).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');const fileName=`${Date.now()}-${index+1}-${safeTitle}${extension}`;const imageFile=await imagesDirectory.getFileHandle(fileName,{create:true});const writer=await imageFile.createWritable();await writer.write(photo);await writer.close();item.image=`images/${fileName}`;}}const selection=[...weeklySelection];const dataFile=await selectedDirectoryHandle.getFileHandle('menu-data.js',{create:true});const writer=await dataFile.createWritable();await writer.write(`window.menuCatalogue = ${JSON.stringify(menuCatalogue,null,2)};\n\nwindow.weeklyMenuSelection = ${JSON.stringify(selection,null,2)};\n`);await writer.close();pendingPhotos.clear();setStatus(saveStatus,`Saved! ${selection.length} item${selection.length===1?'':'s'} will appear on this week's menu.`);renderLibrary();renderActiveItems();}catch(error){console.error(error);setStatus(saveStatus,'Could not save the menu. Please choose the cookiescakes_site folder again and try once more.',true);}});
(async()=>{try{const savedFolder=await getSavedFolder();if(!savedFolder)return;const permission=await savedFolder.queryPermission({mode:'readwrite'});if(permission==='granted')await useFolder(savedFolder);else setStatus(folderStatus,'Your Cookies Cakes website folder is remembered. Click “Choose website folder” to reconnect it.');}catch(error){console.warn(error);}})();
